export default function DataBlock(o,r){this.numDataCodewords=o,this.codewords=r}DataBlock.getDataBlocks=function(o,r,e){if(o.length!=r.totalCodewords)throw"ArgumentException";for(var t=r.getECBlocksForLevel(e),d=0,a=t.getECBlocks(),c=0;c<a.length;c++)d+=a[c].count;for(var n=new Array(d),l=0,s=0;s<a.length;s++){var w=a[s];for(c=0;c<w.count;c++){var f=w.dataCodewords,g=t.ecCodewordsPerBlock+f;n[l++]=new DataBlock(f,new Array(g))}}for(var h=n[0].codewords.length,v=n.length-1;v>=0&&n[v].codewords.length!=h;)v--;v++;var k=h-t.ecCodewordsPerBlock,u=0;for(c=0;c<k;c++)for(s=0;s<l;s++)n[s].codewords[c]=o[u++];for(s=v;s<l;s++)n[s].codewords[k]=o[u++];var B=n[0].codewords.length;for(c=k;c<B;c++)for(s=0;s<l;s++){var C=s<v?c:c+1;n[s].codewords[C]=o[u++]}return n};